    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] direction = new int[n];
        long[] strength = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); direction[i] = (int) in.nval;
            in.nextToken(); strength[i] = (long) in.nval;
        }
        int[] res = survivingBalls(direction, strength);
        StringBuilder sb = new StringBuilder();
        if (res.length == 0) sb.append(-1).append("\n");
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
